p=argparse.ArgumentParser();p.add_argument('returncode',type=int);p.add_argument('output',type=Path);a=p.parse_args();assert a.returncode==0 and not a.output.exists();base=Path('docs/research');manifest=base/'dedup-affine-region-linux-snapshot.json';log=base/'dedup-affine-region-linux-native-retry.log';h=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();r=json.loads(manifest.read_text());snapshot=Path(r['snapshot']);pins={str(p):h(p) for p in [manifest,log,Path(__file__)]};assert all(h(snapshot/k)==v for k,v in r['file_hashes'].items());text=log.read_text();expected={'affine_candidate_search':1,'affine_color':4,'affine_color_heldout_negative':1,'affine_region':3,'affine_region_file':3,'affine_region_grid':2,'region_footprint':2};running=re.findall(r'Running tests/([a-z_]+)\.rs',text);assert sorted(running)==sorted(expected) and len(running)==7
results=re.findall(r'test result: ok\. (\d+) passed; (\d+) failed; (\d+) ignored; (\d+) measured; (\d+) filtered out;',text);assert len(results)==7;assert all(list(map(int,row[1:]))==[0,0,0,0] for row in results);assert [int(v[0]) for v in results]==[expected[name] for name in running]
