assert all(h(k)==v for k,v in pins.items());a.output.write_text(json.dumps({'status':'verified_native_linux_affine_regions','returncode':a.returncode,'tests':sum(expected.values()),'suite_counts':expected,'verified_snapshot_files':len(r['file_hashes']),'input_hashes':pins,'current_code_test_hashes':current,'scope':'Native Linux aarch64 seven focused suites; all immutable snapshot bytes verified. Current new modules/tests match. Current Cargo manifest has subsequent example feature registrations; snapshot is preserved, no Windows/broad corpus/full RSS proof.'},indent=2)+'\n')
